use std::fs;
use std::process::Command;
use tempfile::tempdir;

fn run_case(
    prefix: &str,
    steps: usize,
    cmd: &str,
    target: &str,
    durability: &str,
    db_path: Option<&str>,
    input_path: &str,
) -> Result<(), Box<dyn std::error::Error>> {
    let mut args = vec![cmd, target];
    if let Some(db) = db_path {
        args.push("--db");
        args.push(db);
    }
    args.push("--input-bin");
    args.push(input_path);
    args.push("--durability");
    args.push(durability);

    let output = Command::new(env!("CARGO_BIN_EXE_velvet-ballistics"))
        .args(&args)
        .output()?;

    if !output.status.success() {
        return Err(format!(
            "command failed: {:?}\nstdout: {}\nstderr: {}",
            args,
            String::from_utf8_lossy(&output.stdout),
            String::from_utf8_lossy(&output.stderr)
        )
        .into());
    }

    let stdout = String::from_utf8_lossy(&output.stdout);
    let stderr = String::from_utf8_lossy(&output.stderr);

    let expected_line = format!("run 1: submitted=1 completed=1 failed=0 steps={steps}");
    if stdout.lines().next() != Some(expected_line.as_str()) {
        return Err(format!(
            "unexpected first line. expected: {}\nactual: {}\nfull stdout: {}",
            expected_line,
            stdout.lines().next().unwrap_or("<none>"),
            stdout
        )
        .into());
    }

    if !stdout.ends_with("run completed\n") {
        return Err(format!("stdout does not end with 'run completed\\n': {}", stdout).into());
    }

    if !stderr.is_empty() {
        return Err(format!("unexpected stderr: {}", stderr).into());
    }

    Ok(())
}

